import os
from typing import Any, Dict, List, Optional, Union

from azure.core.credentials import AzureKeyCredential
from azure.ai.documentintelligence import DocumentIntelligenceClient


def _to_number(value: Any) -> Any:
    if value is None:
        return None
    if isinstance(value, (int, float, bool)):
        return value
    if isinstance(value, str):
        s = value.strip()
        if not s:
            return value
        try:
            if "." in s:
                return float(s)
            return int(s)
        except ValueError:
            return value
    return value


def _extract_field_value(field: Any) -> Any:
    if field is None:
        return None

    field_type = getattr(field, "value_type", None) or getattr(field, "type", None)

    if field_type in ("string", "countryRegion", "date", "time", "phoneNumber", "selectionMark"):
        return getattr(field, "value", None)
    if field_type in ("number", "integer", "currency"):
        return _to_number(getattr(field, "value", None))
    if field_type == "boolean":
        return getattr(field, "value", None)
    if field_type == "array":
        items = getattr(field, "value_array", None) or getattr(field, "value", None) or []
        return [_extract_field_value(item) for item in items]
    if field_type == "object":
        obj = getattr(field, "value_object", None) or getattr(field, "value", None) or {}
        return {k: _extract_field_value(v) for k, v in obj.items()}
    if field_type == "address":
        addr = getattr(field, "value_address", None) or getattr(field, "value", None)
        if addr is None:
            return None
        return {
            "street_address": getattr(addr, "street_address", None),
            "city": getattr(addr, "city", None),
            "state": getattr(addr, "state", None),
            "postal_code": getattr(addr, "postal_code", None),
            "country_region": getattr(addr, "country_region", None),
        }
    if field_type == "selectionMark":
        return getattr(field, "value", None)

    return getattr(field, "value", None)


def _extract_key_values_from_key_value_pairs(result: Any) -> Dict[str, Any]:
    extracted: Dict[str, Any] = {}

    kv_pairs = getattr(result, "key_value_pairs", None) or []
    for pair in kv_pairs:
        key_content = None
        value_content = None

        key = getattr(pair, "key", None)
        value = getattr(pair, "value", None)

        if key is not None:
            key_content = getattr(key, "content", None) or getattr(key, "text", None)
        if value is not None:
            value_content = getattr(value, "content", None) or getattr(value, "text", None)

        if key_content:
            extracted[str(key_content).strip()] = value_content

    return extracted


def _extract_layout_text(result: Any) -> Dict[str, Any]:
    pages_output: List[Dict[str, Any]] = []
    pages = getattr(result, "pages", None) or []
    for page in pages:
        lines = []
        for line in getattr(page, "lines", None) or []:
            lines.append(getattr(line, "content", None) or getattr(line, "text", None))
        pages_output.append(
            {
                "page_number": getattr(page, "page_number", None),
                "width": getattr(page, "width", None),
                "height": getattr(page, "height", None),
                "unit": getattr(page, "unit", None),
                "lines": [line for line in lines if line],
            }
        )
    return {"pages": pages_output}


def extract_key_value_pairs(
    document: Union[str, bytes, Any],
    *,
    model_id: Optional[str] = None,
    endpoint: Optional[str] = None,
    api_key: Optional[str] = None,
) -> Dict[str, Any]:
    """
    Extract key-value pairs from a form-like document using Azure AI Document Intelligence.

    Args:
        document: Path to a file, bytes payload, or file-like object.
        model_id: Document Intelligence model id. Defaults to "prebuilt-document".
        endpoint: Azure Document Intelligence endpoint. Defaults to AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT.
        api_key: Azure Document Intelligence key. Defaults to AZURE_DOCUMENT_INTELLIGENCE_KEY.

    Returns:
        A dictionary containing extracted key-value pairs and layout text.
    """
    endpoint = endpoint or os.getenv("AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT")
    api_key = api_key or os.getenv("AZURE_DOCUMENT_INTELLIGENCE_KEY")
    model_id = model_id or "prebuilt-document"

    if not endpoint:
        raise ValueError("Azure Document Intelligence endpoint is required.")
    if not api_key:
        raise ValueError("Azure Document Intelligence key is required.")

    client = DocumentIntelligenceClient(endpoint=endpoint, credential=AzureKeyCredential(api_key))

    analyze_kwargs: Dict[str, Any] = {}
    if isinstance(document, str):
        with open(document, "rb") as f:
            poller = client.begin_analyze_document(model_id=model_id, body=f, **analyze_kwargs)
            result = poller.result()
    else:
        poller = client.begin_analyze_document(model_id=model_id, body=document, **analyze_kwargs)
        result = poller.result()

    structured_fields: Dict[str, Any] = {}
    documents = getattr(result, "documents", None) or []
    for doc in documents:
        fields = getattr(doc, "fields", None) or {}
        for name, field in fields.items():
            structured_fields[name] = _extract_field_value(field)

    key_values = _extract_key_values_from_key_value_pairs(result)
    layout = _extract_layout_text(result)

    return {
        "key_value_pairs": key_values,
        "structured_fields": structured_fields,
        "layout": layout,
    }
